export function translate(locale: Locale, message: string): string {
  if (locale === 'en') return message;
  if (locale === 'ja' && japaneseMessages[message]) return japaneseMessages[message];
  return supplementalMessages[locale]?.[message] ?? messages[locale][message] ?? message;
}

export function localePath(pathname: string, locale: Locale): string {
  const pathWithoutLocale = pathname.replace(/^\/(ja|zh|ar|de)(?=\/|$)/, '') || '/';
  return locale === 'en' ? pathWithoutLocale : `/${locale}${pathWithoutLocale === '/' ? '' : pathWithoutLocale}`;
}

export function withLocale(path: string, locale: Locale): string {
  if (!path.startsWith('/') || path.startsWith('//')) return path;
  const [pathname, suffix = ''] = path.split(/(?=[?#])/u, 2);
  return `${localePath(pathname, locale)}${suffix}`;
}
